#include <algorithm>
#include <cstdint>
#include <vector>

struct Pixel { std::uint8_t b, g, r, a; };
struct RectF { float left, top, right, bottom; };

namespace
{
    std::uint8_t mulDiv255(int c, int a) { return static_cast<std::uint8_t>((c * a + 127) / 255); }
}

Pixel premultiply(Pixel s) { return { mulDiv255(s.b, s.a), mulDiv255(s.g, s.a), mulDiv255(s.r, s.a), s.a }; }

Pixel unpremultiply(Pixel p)
{
    if (p.a == 0) return { 0, 0, 0, 0 };
    auto un = [&](int c) { return static_cast<std::uint8_t>(std::min(255, (c * 255 + p.a / 2) / p.a)); };
    return { un(p.b), un(p.g), un(p.r), p.a };
}

Pixel over(Pixel s, Pixel d)
{
    const int keep{ 255 - s.a };
    auto ch = [&](int sc, int dc) { return static_cast<std::uint8_t>(std::min(255, sc + (dc * keep + 127) / 255)); };
    return { ch(s.b, d.b), ch(s.g, d.g), ch(s.r, d.r), ch(s.a, d.a) };
}

RectF fit(float w, float h, RectF box)
{
    const float bw{ box.right - box.left }, bh{ box.bottom - box.top };
    const float s{ std::min(bw / w, bh / h) };
    const float x{ box.left + (bw - w * s) / 2 }, y{ box.top + (bh - h * s) / 2 };
    return { x, y, x + w * s, y + h * s };
}

RectF fill(float w, float h, RectF box)
{
    const float bw{ box.right - box.left }, bh{ box.bottom - box.top };
    const float s{ std::max(bw / w, bh / h) };
    const float x{ box.left + (bw - w * s) / 2 }, y{ box.top + (bh - h * s) / 2 };
    return { x, y, x + w * s, y + h * s };
}

std::vector<Pixel> halve(const std::vector<Pixel>& image, int w, int h)
{
    std::vector<Pixel> out(static_cast<std::size_t>((w / 2) * (h / 2)));
    for (int y{ 0 }; y < h / 2; ++y)
        for (int x{ 0 }; x < w / 2; ++x)
        {
            int sum[4]{};
            for (int dy{ 0 }; dy < 2; ++dy)
                for (int dx{ 0 }; dx < 2; ++dx)
                {
                    const Pixel& p{ image[static_cast<std::size_t>((2 * y + dy) * w + 2 * x + dx)] };
                    sum[0] += p.b; sum[1] += p.g; sum[2] += p.r; sum[3] += p.a;
                }
            out[static_cast<std::size_t>(y * (w / 2) + x)] = { static_cast<std::uint8_t>((sum[0] + 2) / 4), static_cast<std::uint8_t>((sum[1] + 2) / 4),
                                                               static_cast<std::uint8_t>((sum[2] + 2) / 4), static_cast<std::uint8_t>((sum[3] + 2) / 4) };
        }
    return out;
}
